WITH kept AS (SELECT s.* FROM stores s WHERE NOT EXISTS (SELECT 1 FROM inventory ch WHERE ch.store_id = s.id AND ch.last_restock >= s.opened_date)) SELECT DATE_TRUNC('MONTH', opened_date) AS activity_month, region, city, COUNT(*) AS num_rows, SUM(CASE WHEN city = 'Berlin' THEN sqft ELSE 0 END) AS berlin_sqft, SIZE(COLLECT_SET(region)) AS num_regions, SUM(sqft) FILTER (WHERE region = 'East') AS east_total_sqft, COUNT(*) FILTER (WHERE region = 'North') AS north_rows FROM kept GROUP BY 1, 2, 3 HAVING east_total_sqft > 0 ORDER BY east_total_sqft;
